pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response time is less than 1000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

pm.test("Response body is valid JSON and has expected structure", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("status", "success");
    pm.expect(jsonData).to.have.property("data");
    pm.expect(jsonData.data).to.have.property("serverTimeISO");
    pm.expect(jsonData.data).to.have.property("timestamp");
    pm.expect(jsonData.data).to.have.property("platform");
});

